"""Tetrad's GIN on data generated by latent variables and their indicators.

``fit`` writes the data to a CSV, starts ``java`` once on ``TetradGinDriver.java`` against
tetrad-lib's shaded jar, and reads the clusters back from the text file the driver writes. Tetrad's
GIN takes a raw marginal independence test; the driver passes Tetrad's KCI under its defaults, a
Gaussian kernel with a median-distance bandwidth and the gamma approximation. That is the family
of the gamma-HSIC test Andrey's and causal-learn's GIN run, each with its own bandwidth rule, so the
packages can decide a test differently at equal ``alpha`` (0.05 in all three). Tetrad's GIN tests
the residual against each variable it names, which causal-learn needs a fix for
(:mod:`~andrey_bench.adapters.causal_learn_gin`).

The driver runs the warm-up searches the harness asks for in the same JVM, then times the
``Gin.search`` call alone, so the record's ``wall_s`` is Tetrad's search inside the JVM and its
``process_s`` the whole call, with the JVM start, the compile of the driver, and the CSV round
trip. The JVM sees only the fit's cores (``-XX:ActiveProcessorCount``).

``ANDREY_BENCH_TETRAD_GIN_JAR`` names the jar: GIN needs tetrad-lib 7.6.10, which no causal-cmd
release bundles. ``ANDREY_BENCH_JAVA`` names the ``java`` executable, by default the one on
``PATH``; it needs the ``jdk.compiler`` module, which runs a source file. The README's "GIN" section
gives the jar's release, download, and checksum.
"""

from __future__ import annotations

import functools
import os
import re
import subprocess
import tempfile
import zipfile
from pathlib import Path
from typing import Any, Mapping

import numpy as np

from andrey_bench.adapters.gin_convert import encode_clusters, latent_dag
from andrey_bench.adapters.tetrad_cmd import _java, _processors, _tagged, read_search_s

JAR_ENV = "ANDREY_BENCH_TETRAD_GIN_JAR"
DRIVER = Path(__file__).with_name("TetradGinDriver.java")

_DEFAULTS = {"alpha": 0.05, "indep_test": "kci"}


def _jar() -> Path:
    jar = os.environ.get(JAR_ENV, "").strip()
    if not jar or not Path(jar).is_file():
        raise RuntimeError(f"set ${JAR_ENV} to tetrad-lib's shaded jar (README: GIN)")
    return Path(jar)


@functools.cache
def versions() -> str:
    """Name the releases a fit runs: ``tetrad-lib 7.6.10, Java 21.0.12``."""
    tetrad = "unknown"
    jar = Path(os.environ.get(JAR_ENV, "").strip())
    if jar.is_file():
        with zipfile.ZipFile(jar) as archive:
            name = "META-INF/maven/io.github.cmu-phil/tetrad-lib/pom.properties"
            if name in archive.namelist():
                text = archive.read(name).decode()
                tetrad = re.search(r"^version=(.+)$", text, re.M).group(1).strip()
    java = "unknown"
    try:
        done = subprocess.run([_java(), "-version"], capture_output=True, text=True)
        match = re.search(r'version "([^"]+)"', done.stderr)
        java = match.group(1) if match else java
    except RuntimeError:  # no java
        pass
    return f"tetrad-lib {tetrad}, Java {java}"


def read_clusters(text: str, tag: str) -> list[list[int]]:
    """Return the clusters on the driver's ``tag`` line, as lists of column indices."""
    body = _tagged(text, tag)
    return [[int(i) for i in part.split()] for part in body.split(";") if part.strip()]


class TetradGIN:
    """Solution adapter for Tetrad's GIN; ``fit`` runs the driver once.

    ``search_s`` and ``warmup`` follow the harness's convention for a search timed in another
    process (``contracts.SolutionAdapter``). Satisfies :class:`andrey_bench.contracts.SolutionAdapter`.
    """

    name: str = "tetrad.gin"
    package: str = "tetrad"
    backend: str = "jvm"
    mode: str = "serial"
    algorithm: str = "gin"
    output_type: str = "dag"
    search_s: float | None = None
    warmup: int = 0

    @property
    def package_version(self) -> str:
        """tetrad-lib's and Java's releases (:func:`versions`)."""
        return versions()

    def setup(self) -> None:
        """Check ``java``, its compiler module, and the jar before timing."""
        modules = subprocess.run(
            [_java(), "--list-modules"], check=True, capture_output=True, text=True
        ).stdout
        if not re.search(r"^jdk\.compiler@", modules, re.M):
            raise RuntimeError(f"{_java()} has no jdk.compiler module to run {DRIVER.name}")
        _jar()

    def params(self) -> dict[str, Any]:
        """Return the settings the driver runs."""
        return dict(_DEFAULTS)

    def fit(self, data: np.ndarray, params: Mapping[str, Any]) -> np.ndarray:
        """Run the driver, set ``search_s``, and return the clusters and their order."""
        settings = {**_DEFAULTS, **params}
        x = np.asarray(data, dtype=np.float64)
        d = x.shape[1]
        with tempfile.TemporaryDirectory(prefix="andrey_bench_tetrad_gin_") as tmp:
            work = Path(tmp)
            csv, result = work / "data.csv", work / "fit_out.txt"
            header = ",".join(f"x{j}" for j in range(d))
            np.savetxt(csv, x, delimiter=",", fmt="%.17g", header=header, comments="")
            command = [
                _java(),
                f"-XX:ActiveProcessorCount={_processors()}",
                f"-Djava.util.prefs.userRoot={work}",  # keeps Java's preferences out of $HOME
                "--class-path",
                str(_jar()),
                str(DRIVER),
                str(csv),
                repr(float(settings["alpha"])),
                str(self.warmup),
                str(result),
            ]
            done = subprocess.run(command, capture_output=True, text=True, cwd=work)
            if done.returncode != 0 or not result.is_file():
                raise RuntimeError(
                    f"{DRIVER.name} exited {done.returncode}: {done.stderr.strip()[-500:]}"
                )
            text = result.read_text()
        self.search_s = read_search_s(text)
        ordered = read_clusters(text, "Ordered clusters:")
        unordered = read_clusters(text, "Unordered clusters:")
        return encode_clusters(ordered, unordered, d)

    def to_structure(self, native: np.ndarray) -> Any:
        """Build the latent DAG from the clusters outside the timed region."""
        return latent_dag(native)
